if (!msg._state_changed) { node.status({ fill: 'grey', shape: 'dot', text: 'no change' }); return null; }
function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const d = msg.device;
const vals = [d.ts, d.id, d.type, d.location, JSON.stringify(d.state), msg.event_type ?? 'state_change'];
msg.topic = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (' + vals.map(esc).join(',') + ')';
node.status({ fill: 'green', shape: 'dot', text: `log: ${d.id}` });
return msg;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const gateway = msg._lwt_gateway;
const isOnline = msg._lwt_online;
const devCount = msg._lwt_dev_count || 0;
const vals = [new Date().toISOString(), gateway, 'gateway', '', JSON.stringify({ online: isOnline, devices_affected: devCount }), isOnline ? 'gateway_online' : 'gateway_offline'];
msg.topic = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (' + vals.map(esc).join(',') + ')';
node.status({ fill: isOnline ? 'green' : 'red', shape: 'dot', text: gateway + ': ' + (isOnline ? 'ONLINE' : 'OFFLINE') });
return msg;

const d = msg.device;
const state = d.state || {};

function esc(v) {
    if (v === null || v === undefined) return 'NULL';
    if (typeof v === 'number') return String(v);
    return "'" + String(v).replace(/'/g, "''") + "'";
}

const now = d.ts;
const deviceId = d.id;
const deviceType = d.type;

const rows = [];
for (const [key, val] of Object.entries(state)) {
    let attrValue = 'NULL';
    let attrStr = 'NULL';
    let attrType = typeof val;

    if (typeof val === 'number') {
        attrValue = String(val);
        attrStr = esc(String(val));
    } else if (typeof val === 'boolean') {
        attrStr = esc(val ? 'true' : 'false');
        attrType = 'bool';
    } else {
        attrStr = esc(String(val));
    }

    let rawAttrId = 'NULL';
    if (key.startsWith('raw_')) {
        rawAttrId = esc(key.slice(4));
    } else if (d.raw && d.raw['EF00/' + key]) {
        rawAttrId = esc(key);
    }

    rows.push(`(${esc(now)}, ${esc(deviceId)}, ${esc(deviceType)}, ${esc(key)}, ${attrValue}, ${attrStr}, ${esc(attrType)}, ${rawAttrId})`);
}

if (rows.length === 0) return null;

msg.topic = 'INSERT INTO device_metric (ts, device_id, device_type, attr_name, attr_value, attr_str, attr_type, raw_attr_id) VALUES ' + rows.join(',');
node.status({ fill: 'green', shape: 'dot', text: rows.length + ' metrics' });
return msg;
